package com.clinicbooking.medicalrecord.infrastructure.out.persistence;
import com.clinicbooking.medicalrecord.domain.*; import org.junit.jupiter.api.Test; import org.mockito.ArgumentCaptor; import java.time.LocalDateTime; import java.util.*; import static org.junit.jupiter.api.Assertions.*; import static org.mockito.Mockito.*;
class MedicalRecordPersistenceAdapterTest {
 @Test void persistsEncounterAndPrescriptions(){MedicalRecordJpaRepository jpa=mock(MedicalRecordJpaRepository.class);MedicalPrescriptionJpaRepository rx=mock(MedicalPrescriptionJpaRepository.class);when(jpa.findById(any())).thenReturn(Optional.empty());when(jpa.save(any())).thenAnswer(i->i.getArgument(0));when(rx.save(any())).thenAnswer(i->i.getArgument(0));var adapter=new MedicalRecordPersistenceAdapter(jpa,rx);var m=new MedicalRecord(null,UUID.randomUUID(),UUID.randomUUID(),120,80,37,80,98,LocalDateTime.now());m.prescribe("Drug");adapter.save(m);ArgumentCaptor<MedicalRecordEntity> c=ArgumentCaptor.forClass(MedicalRecordEntity.class);verify(jpa).save(c.capture());assertEquals("",c.getValue().allergies);assertEquals("V",c.getValue().triage);verify(rx).deleteByEncounterId(m.getId());ArgumentCaptor<MedicalPrescriptionEntity> prescription=ArgumentCaptor.forClass(MedicalPrescriptionEntity.class);verify(rx).save(prescription.capture());assertEquals("Drug",prescription.getValue().medication);assertTrue(prescription.getValue().active);}
 @Test void listsByPatientAndDoctor(){MedicalRecordJpaRepository jpa=mock(MedicalRecordJpaRepository.class);var e=new MedicalRecordEntity();e.id=UUID.randomUUID();e.patientId=UUID.randomUUID();e.doctorId=UUID.randomUUID();e.createdAt=LocalDateTime.now();e.systolic=120;e.diastolic=80;e.temperature=37;e.heartRate=80;e.spo2=98;e.allergies="";when(jpa.findByPatientId(e.patientId)).thenReturn(List.of(e));when(jpa.findByDoctorId(e.doctorId)).thenReturn(List.of(e));var a=new MedicalRecordPersistenceAdapter(jpa,mock(MedicalPrescriptionJpaRepository.class));assertEquals(1,a.findByPatient(e.patientId).size());assertEquals(1,a.findByDoctor(e.doctorId).size());}

 @Test void readsAndRehydratesEncounter(){MedicalRecordJpaRepository jpa=mock(MedicalRecordJpaRepository.class);var e=new MedicalRecordEntity();e.id=UUID.randomUUID();e.patientId=UUID.randomUUID();e.doctorId=UUID.randomUUID();e.createdAt=LocalDateTime.now();e.systolic=120;e.diastolic=80;e.temperature=37;e.heartRate=80;e.spo2=98;e.triage="V";e.closed=true;e.diagnosisCode="J06.9";e.evolution="stable";e.disabilityDays=1;when(jpa.findById(e.id)).thenReturn(Optional.of(e));MedicalPrescriptionJpaRepository rx=mock(MedicalPrescriptionJpaRepository.class);var p=new MedicalPrescriptionEntity();p.medication="Rx";p.active=true;when(rx.findByEncounterIdAndActiveTrue(e.id)).thenReturn(List.of(p));var m=new MedicalRecordPersistenceAdapter(jpa,rx).findById(e.id).orElseThrow();assertTrue(m.isClosed());assertEquals("Rx",m.getPrescriptions().get(0));assertEquals("J06.9",m.getDiagnosisCode());}
}
